<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class Invoice extends Model { protected $fillable=['invoice_number','public_token','customer_id','period','issued_at','due_date','subtotal','discount','penalty','tax_rate','tax_amount','total','status','paid_at','payment_url','payment_reference','payment_expired_at','notes']; protected $casts=['issued_at'=>'date','due_date'=>'date','subtotal'=>'integer','discount'=>'integer','penalty'=>'integer','tax_rate'=>'decimal:2','tax_amount'=>'integer','total'=>'integer','paid_at'=>'datetime','payment_expired_at'=>'datetime']; public function customer():BelongsTo{return $this->belongsTo(Customer::class)->withTrashed();} public function payments():HasMany{return $this->hasMany(Payment::class);} public function items():HasMany{return $this->hasMany(InvoiceItem::class);} public function getIsOverdueAttribute():bool{return $this->status==='unpaid' && now(config('billing.timezone'))->startOfDay()->gt($this->due_date->copy()->addDays($this->customer?->grace_days ?? config('billing.grace_days')));} }
